async Task User(Guid id){db.ChangeTracker.Clear();await current.ChonAsync(id);}
async Task Pass(string name,Func<Task> action){db.ChangeTracker.Clear();await action();report.Add(name);Console.WriteLine("PASS "+name);}
async Task Denied(Func<Task> action){try{await action();throw new Exception("Expected rejection");}catch(LoiNghiepVu){}catch(DbUpdateConcurrencyException){}catch(Microsoft.Data.SqlClient.SqlException e)when(e.Number>=51000){}finally{db.ChangeTracker.Clear();}}
