// Exercise both transaction orders with independent SQL connections and the same application lock.
async Task Race(bool hideFirst)
{
 await User(tutor);await Approve();await State("Hien");var who=Guid.NewGuid();db.Add(new NguoiThamGia{Id=who,HoTen="Race learner",LoaiNguoi="HocSinh"});await db.SaveChangesAsync();
 using var a=Db();using var b=Db();var ah=new DefaultHttpContext{Session=new TestSession()};var bh=new DefaultHttpContext{Session=new TestSession()};var ac=new NguoiDungMauService(a,new TestAccessor{HttpContext=ah});var bc=new NguoiDungMauService(b,new TestAccessor{HttpContext=bh});await ac.ChonAsync(tutor);await bc.ChonAsync(who);
 var ps=new HoSoGiaSuService(a,ac,new MonHocCatalog(a),new TepService(a,ac,new QuyenLopHocService(a,ac),env),new ThongBaoService(a,ac));var ls=new KetNoiService(b,bc,new ThongBaoService(b,bc));
 var first=hideFirst?a:b;await using var tx=await first.Database.BeginTransactionAsync();await HoSoLock.KhoaAsync(first,tutor);
 Task second=hideFirst?ls.GuiLienHeAsync(new(){DoiTuongId=tutor,LoiNhan="racing"}):ps.DoiTrangThaiAsync("An",(await ps.LayDeSuaAsync()).RowVersion!);
 await Task.Delay(100);Check(!second.IsCompleted,"Second transaction did not wait for shared lock");
 if(hideFirst)await a.Database.ExecuteSqlInterpolatedAsync($"UPDATE dbo.HoSoGiaSu SET DangHienThi=0 WHERE GiaSuId={tutor}");
 else await b.Database.ExecuteSqlInterpolatedAsync($"INSERT dbo.YeuCauLienHe(GiaSuId,BenHocId,NguoiGuiId,LoiNhan,TrangThai) VALUES({tutor},{who},{who},N'committed before hide','ChoPhanHoi')");
 await tx.CommitAsync();if(hideFirst)await Denied(()=>second);else await second;
 db.ChangeTracker.Clear();Check(await db.Set<YeuCauLienHe>().AnyAsync(x=>x.GiaSuId==tutor&&x.BenHocId==who)==!hideFirst,"Incorrect contact outcome");
}
await Pass("Concurrent hide first rejects later contact",()=>Race(true));
await Pass("Concurrent contact first is retained after hiding",()=>Race(false));
await Pass("Profile pagination counts tutors, not subjects",async()=>{await User(learner);for(int i=0;i<11;i++){var id=Guid.NewGuid();var h=Guid.NewGuid();db.Add(new NguoiThamGia{Id=id,HoTen=$"Pagination {tutor:N} {i}",LoaiNguoi="GiaSu"});await db.SaveChangesAsync();db.Add(new GiaSu{TaiKhoanId=id});await db.SaveChangesAsync();db.Add(new HoSoGiaSu{Id=h,GiaSuId=id,TrinhDo="Đại học",ChuyenMon="Math",KinhNghiem="2",MoTa="Test",KhuVuc="Hà Nội",DayTrucTuyen=true,DangHienThi=true,TrangThaiDuyet="DaDuyet"});await db.SaveChangesAsync();db.AddRange(new HoSoGiaSuMonDay{HoSoGiaSuId=h,MonHocId=1,PhamViDay="10–12",HocPhiDeXuat=100000,DonViHocPhi="VND/Gio"},new HoSoGiaSuMonDay{HoSoGiaSuId=h,MonHocId=2,PhamViDay="10–12",HocPhiDeXuat=200000,DonViHocPhi="VND/Buoi"});await db.SaveChangesAsync();}var p1=await search.TimAsync(new(){TuKhoa=$"Pagination {tutor:N}"});var p2=await search.TimAsync(new(){TuKhoa=$"Pagination {tutor:N}",Trang=2});Check(p1.Total==11&&p1.Items.Count==9&&p2.Items.Count==2&&!p1.Items.Select(x=>x.Id).Intersect(p2.Items.Select(x=>x.Id)).Any(),"Pagination duplicates");});
